const source = $('Execute Workflow Trigger').item.json || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const rawText = String(source.rawText || source.text || message.text || message.caption || payload.text || '').trim();

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;');
}

function escapeSql(value = '') {
  return String(value || '').replace(/'/g, "''");
}

function code(value = '') {
  return `<code>${escapeHtml(value)}</code>`;
}

function parseDuration(value) {
  const text = normalize(value);
  if (!text) return null;
  if (/\b(vinh vien|khong het han|forever)\b/.test(text)) {
    return { forever: true, ms: null, label: 'Vinh vien' };
  }

  const compact = text.match(/(\d+)\s*(h|d|w)\b/);
  if (compact) {
    const amount = Number(compact[1]);
    const unit = compact[2];
    if (unit === 'h') return { forever: false, ms: amount * 3600 * 1000, label: `${amount}h` };
    if (unit === 'd') return { forever: false, ms: amount * 24 * 3600 * 1000, label: `${amount}d` };
    if (unit === 'w') return { forever: false, ms: amount * 7 * 24 * 3600 * 1000, label: `${amount}w` };
  }

  const verbose = text.match(/(\d+)\s*(gio|ngay|tuan|thang|hour|day|week|month)\b/);
  if (verbose) {
    const amount = Number(verbose[1]);
    const unit = verbose[2];
    if (unit === 'gio' || unit === 'hour') return { forever: false, ms: amount * 3600 * 1000, label: `${amount} gio` };
    if (unit === 'ngay' || unit === 'day') return { forever: false, ms: amount * 24 * 3600 * 1000, label: `${amount} ngay` };
    if (unit === 'tuan' || unit === 'week') return { forever: false, ms: amount * 7 * 24 * 3600 * 1000, label: `${amount} tuan` };
    if (unit === 'thang' || unit === 'month') return { forever: false, ms: amount * 30 * 24 * 3600 * 1000, label: `${amount} thang` };
  }

  return null;
}

function isPrivateHost(hostname) {
  const host = String(hostname || '').toLowerCase();
  if (!host) return true;
  if (host === 'localhost' || host === '0.0.0.0' || host === '127.0.0.1' || host === '::1') return true;
  if (host.endsWith('.local')) return true;
  if (/^10\./.test(host)) return true;
  if (/^192\.168\./.test(host)) return true;
  if (/^172\.(1[6-9]|2\d|3[0-1])\./.test(host)) return true;
  return false;
}

const helpText = [
  '🔗 <b>Short Link</b>',
  '',
  'Minh ho tro rut gon link thanh dang:',
  code('https://go.huynhminh.com/<id>'),
  '',
  'Vi du:',
  code('rut gon link https://example.com'),
  code('rut gon link https://example.com trong 7 ngay'),
  code('short link https://example.com 24h'),
  code('tao link ngan https://example.com vinh vien'),
  '',
  'Mac dinh:',
  '- neu khong ghi thoi gian, link song 30 ngay',
  '- co the dung: 1h, 24h, 7d, 30d, 1 tuan, 1 thang, vinh vien'
].join('\n');

if (!chatId) {
  throw new Error('Missing chatId while preparing Short Link Telegram request.');
}

const normalized = normalize(rawText);
const isHelp = !rawText || /\b(shortlink help|short link help|help shortlink|huong dan shortlink)\b/.test(normalized);
if (isHelp) {
  return [{ json: { ...source, payload, message, chatId, rawText, normalizedText: normalized, isHelp: true, isReady: false, response: helpText } }];
}

const urlMatch = rawText.match(/https?:\/\/[^\s<>"']+/i);
if (!urlMatch) {
  return [{ json: { ...source, payload, message, chatId, rawText, normalizedText: normalized, isHelp: false, isReady: false, response: '❌ <b>Thieu URL</b>\n\nVi du: <code>rut gon link https://example.com trong 7 ngay</code>' } }];
}

const longUrl = urlMatch[0].replace(/[),.;!?]+$/, '');
const ttlSource = rawText.replace(longUrl, ' ').trim();
const requestedTtl = parseDuration(ttlSource);
const defaultTtl = parseDuration($env.SHORTLINK_DEFAULT_TTL || '30d') || { forever: false, ms: 30 * 24 * 3600 * 1000, label: '30d' };
const maxDays = Number($env.SHORTLINK_MAX_TTL_DAYS || 365) || 365;
const maxMs = maxDays * 24 * 3600 * 1000;
const allowLocal = String($env.SHORTLINK_ALLOW_LOCAL || 'false').toLowerCase() === 'true';
const publicBaseUrl = String($env.SHORTLINK_PUBLIC_BASE_URL || 'https://go.huynhminh.com').replace(/\/+$/, '');

let parsedUrl;
try {
  parsedUrl = new URL(longUrl);
} catch (error) {
  return [{ json: { ...source, payload, message, chatId, rawText, normalizedText: normalized, isHelp: false, isReady: false, response: '❌ <b>URL khong hop le</b>\n\nChi nhan <code>http://</code> hoac <code>https://</code>.' } }];
}

const protocol = String(parsedUrl.protocol || '').toLowerCase();
if (protocol !== 'http:' && protocol !== 'https:') {
  return [{ json: { ...source, payload, message, chatId, rawText, normalizedText: normalized, isHelp: false, isReady: false, response: '❌ <b>Protocol khong duoc ho tro</b>\n\nChi nhan <code>http://</code> va <code>https://</code>.' } }];
}

if (!parsedUrl.host) {
  return [{ json: { ...source, payload, message, chatId, rawText, normalizedText: normalized, isHelp: false, isReady: false, response: '❌ <b>URL khong co host hop le</b>' } }];
}

if (!allowLocal && isPrivateHost(parsedUrl.hostname)) {
  return [{ json: { ...source, payload, message, chatId, rawText, normalizedText: normalized, isHelp: false, isReady: false, response: '❌ <b>Khong cho phep URL noi bo/local</b>\n\nBan co the bat <code>SHORTLINK_ALLOW_LOCAL=true</code> neu that su can.' } }];
}

let ttl = requestedTtl || defaultTtl;
let wasClamped = false;
let clampMessage = '';
if (!ttl.forever && ttl.ms > maxMs) {
  ttl = { forever: false, ms: maxMs, label: `${maxDays} ngay` };
  wasClamped = true;
  clampMessage = `TTL duoc gioi han toi da ${maxDays} ngay.`;
}

const expiresAt = ttl.forever ? null : new Date(Date.now() + ttl.ms);
const expiresAtIso = expiresAt ? expiresAt.toISOString() : null;
const expiresAtDisplay = expiresAt ? expiresAt.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false }) : 'Vinh vien';
const crypto = require('crypto');
const hash = crypto.createHash('sha256').update(`${longUrl}|${publicBaseUrl}`).digest('hex');
const candidateId8 = hash.slice(0, 8);
const candidateId10 = hash.slice(0, 10);
const candidateId12 = hash.slice(0, 12);
const lookupSql = `SELECT id, long_url, short_url, host, clicks, created_at, expires_at, updated_at, last_clicked_at FROM short_links WHERE long_url = '${escapeSql(longUrl)}' OR id IN ('${candidateId8}', '${candidateId10}', '${candidateId12}') ORDER BY created_at DESC;`;

return [{
  json: {
    ...source,
    payload,
    message,
    chatId,
    rawText,
    normalizedText: normalized,
    isHelp: false,
    isReady: true,
    response: '',
    longUrl,
    host: parsedUrl.host,
    publicBaseUrl,
    requestedTtlLabel: requestedTtl ? requestedTtl.label : defaultTtl.label,
    effectiveTtlLabel: ttl.forever ? 'Vinh vien' : ttl.label,
    expiresAtIso,
    expiresAtDisplay,
    expiresAtSql: expiresAtIso ? `'${expiresAtIso}'::timestamptz` : 'NULL',
    wasClamped,
    clampMessage,
    maxTtlDays: maxDays,
    allowLocal,
    candidateId8,
    candidateId10,
    candidateId12,
    lookupSql
  }
}];

const source = $('Prepare Shortlink Request').item.json || {};
const rows = $input.all().map((item) => item.json || {}).filter((row) => row.id || row.long_url);

function escapeSql(value = '') {
  return String(value || '').replace(/'/g, "''");
}

function isExpired(row) {
  return Boolean(row.expires_at && new Date(row.expires_at).getTime() <= Date.now());
}

const sameUrl = rows.find((row) => row.long_url === source.longUrl);
const byId = new Map(rows.filter((row) => row.id).map((row) => [row.id, row]));
const candidates = [source.candidateId8, source.candidateId10, source.candidateId12];
let persistSql = '';
let selectedId = '';
let selectedShortUrl = '';
let response = '';

if (sameUrl) {
  selectedId = sameUrl.id;
  selectedShortUrl = sameUrl.short_url || `${source.publicBaseUrl}/${sameUrl.id}`;
  if (isExpired(sameUrl)) {
    persistSql = `UPDATE short_links SET expires_at = ${source.expiresAtSql}, updated_at = now() WHERE id = '${escapeSql(sameUrl.id)}' RETURNING id, long_url, short_url, host, clicks, created_at, expires_at, updated_at, last_clicked_at;`;
  } else {
    persistSql = `SELECT id, long_url, short_url, host, clicks, created_at, expires_at, updated_at, last_clicked_at FROM short_links WHERE id = '${escapeSql(sameUrl.id)}' LIMIT 1;`;
  }
} else {
  const freeCandidate = candidates.find((id) => !byId.has(id));
  if (!freeCandidate) {
    response = '❌ <b>Khong tao duoc short link</b>\n\nTat ca candidate ID deu bi collision. Hay thu lai sau.';
  } else {
    selectedId = freeCandidate;
    selectedShortUrl = `${source.publicBaseUrl}/${selectedId}`;
    persistSql = `INSERT INTO short_links (id, long_url, short_url, host, expires_at, created_at, updated_at) VALUES ('${selectedId}', '${escapeSql(source.longUrl)}', '${escapeSql(selectedShortUrl)}', '${escapeSql(source.host)}', ${source.expiresAtSql}, now(), now()) RETURNING id, long_url, short_url, host, clicks, created_at, expires_at, updated_at, last_clicked_at;`;
  }
}

return [{
  json: {
    ...source,
    id: selectedId,
    shortUrl: selectedShortUrl,
    persistSql,
    response,
    canPersist: Boolean(persistSql)
  }
}];

const source = $('Prepare Shortlink Request').item.json || {};
const row = $input.item.json || {};

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;');
}

const shortUrl = row.short_url || source.shortUrl || '';
const longUrl = row.long_url || source.longUrl || '';
const expiresAt = row.expires_at ? new Date(row.expires_at) : null;
const expiresAtDisplay = expiresAt
  ? expiresAt.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false })
  : 'Vinh vien';

let text = '🔗 <b>Da tao link ngan</b>\n\n';
text += 'Short URL:\n';
text += `<code>${escapeHtml(shortUrl)}</code>\n\n`;
text += 'Het han:\n';
text += `<code>${escapeHtml(expiresAtDisplay)}</code>\n\n`;
text += 'Long URL:\n';
text += `<code>${escapeHtml(longUrl)}</code>`;
if (source.wasClamped && source.clampMessage) {
  text += `\n\n<i>${escapeHtml(source.clampMessage)}</i>`;
}

return [{ json: { chatId: source.chatId, text } }];

const source = $input.item.json || $('Prepare Shortlink Request').item.json || {};
if (!source.chatId) {
  throw new Error('Missing chatId while formatting Short Link Telegram fallback response.');
}
return [{ json: { chatId: source.chatId, text: source.response || '❌ <b>Khong the xu ly short link</b>' } }];
